          checked += 1;
          if (!sub || sub.nodeType !== 1 || PRUNE_TAGS.has(sub.tagName) || SKIP_SELF_TAGS.has(sub.tagName) || isOwnElement(sub)) continue;
          if (sub === dialogEl || sub === lastSettingsNav) continue;
