        if (sidebarReconcileTimer) clearTimeout(sidebarReconcileTimer);
        if (hoverRaf) cancelAnimationFrame(hoverRaf);
        if (overlayNavTimer) clearTimeout(overlayNavTimer);
        clearTimeout(settle1);
        clearTimeout(settle2);
        clearDomMarks();
